SELECT jsonb_build_object('events',(SELECT jsonb_agg(jsonb_build_object('id_evento',e.id_evento,'name',e.nome_evento,'tag',e.tag,'start',e.data_inicial,'finish',e.data_final,'city',e.cidade,'state',e.estado,'active',e.ativo,'redirect',e.tag_301,'description',e.descricao,'homepage',e.url_hotsite,'registration',e.url_inscricao,'regulation',e.url_regulamento,'family',e.id_agrega_evento,'results',(SELECT count(*) FROM tb_resultados r WHERE r.id_evento=e.id_evento),'courses',(SELECT jsonb_agg(jsonb_build_object('id',p.id_evento_percurso,'distance',p.percurso_evento,'date',p.data_percurso)) FROM tb_evento_corridas_percursos p WHERE p.id_evento=e.id_evento))) FROM tb_evento_corridas e WHERE tag IN ('2026-corrida-adc-zf-clube','2027-corrida-adc-zf-clube','2026-corrida-e-caminhada-outubro-rosa-ro','2026-corrida-e-caminhada-outubro-rosa-chupinguaia')))::text AS payload